from django.db import migrations, models


def enable_ims_where_wms(apps, schema_editor):
    """IMS takes Inventory + Purchase Orders over from WMS: every store with
    WMS on gets IMS on, and every WMS staff login gets IMS too - nobody
    loses a page they had."""
    OrganizationModule = apps.get_model("core", "OrganizationModule")
    Membership = apps.get_model("core", "Membership")

    for org_id in OrganizationModule.objects.filter(module="wms", is_enabled=True).values_list(
        "organization_id", flat=True
    ):
        OrganizationModule.objects.update_or_create(
            organization_id=org_id, module="ims", defaults={"is_enabled": True}
        )

    for membership in Membership.objects.all():
        modules = list(membership.allowed_modules or [])
        if "wms" in modules and "ims" not in modules:
            modules.insert(modules.index("wms"), "ims")
            membership.allowed_modules = modules
            membership.save(update_fields=["allowed_modules"])


